using System;
using System.Text;
using UnityEngine;
using LWS.TruckSports;
using LWS.TruckBowling;
namespace LWS.TruckCurling {
public enum CurlingPhase {Approach,Slide,DeliveryResult,EndResult,Complete}
public sealed class CurlingMatch:SportsEventSession {
 public CurlingStone[] stones;public SportsEventCamera cabCamera;public Camera houseCamera;public GameObject cab;public float slideDeceleration=.65f,earlyCurlRate=.07f,curlBudget=.22f,maximumResolution=70;
 public CurlingPhase Phase{get;private set;}public int End{get;private set;}public int Delivery{get;private set;}public int Hammer{get;private set;}=1;public int[] scores=new int[2];public int[] delivered=new int[2];readonly int[] rosterCursor=new int[2];public int EndsScored{get;private set;}public int GuardViolations{get;private set;}public int PhysicalContacts;public int ActiveTeam=>CurlingRules.TeamFor(Delivery,Hammer);public int ActiveSlot=>(ActiveTeam==0?0:teamA)+(rosterCursor[ActiveTeam]%(ActiveTeam==0?teamA:teamB));public CurlingStone Current=>stones[Mathf.Min(Delivery,15)];
 readonly Vector3[] before=new Vector3[16],positions=new Vector3[16];readonly Quaternion[] rotations=new Quaternion[16];readonly bool[] existed=new bool[16],protectedGuard=new bool[16],beforeHit=new bool[16],beforeGuard=new bool[16],valid=new bool[16];readonly int[] teams=new int[16];readonly StringBuilder text=new StringBuilder(1000);float timer,quiet,slideTime,usedCurl,aimSpeed,aiCurl;Vector3 aim;Quaternion stableYaw;string notice="";
 public override string Title=>"TRUCK CURLING";public override int MinimumPlayers=>2;public override int MaximumPlayers=>8;public override bool TeamSport=>true;public override bool UsesAction=>false;public int ConfiguredEnds=>option==0?2:option==1?4:8;public override string SourcePolicy=>"TURN-BASED HOT SEAT · Shared sources allowed; only the current participant drives.\nSeparate assignments and left/right shared sticks are also supported.";public override string OptionLabel=>ConfiguredEnds+" ENDS · EIGHT DELIVERIES PER TEAM";
 public override void NormalizeSetup(){base.NormalizeSetup();setup.mode=BowlingMode.HotSeat;}
 public override string Help=>"TRUCK CURLING · THE TRUCK IS THE STONE\nTwo teams of one to four. Eight alternating deliveries per team per end; roster members rotate. Choose2 /4 /8 ends (default4). A tied match continues into extra ends. Only one truck receives control at a time; hot seat may share a source, or use separately assigned inputs.\n\nFIRST PERSON: drive and steer in the preparation area. Back input brakes before reversing. The 234m sheet has a 30m approach. Entry speed maps linearly to release speed (20m/s entry =14.8m/s release); 25% is a short slide and full power reaches the far house. Crossing the release line commits your direction and disables the engine/wheels. Steer left/right for a small bounded curl during the first four seconds, then slide freely. There are no sweepers, late propulsion or hidden button correction. Watch speed, the release stripe and tactical house inset.\n\nEvery truck has the same visible circular scoring/collision footprint. Touching the house qualifies. Only the team nearer the button scores: one point per own in-house truck closer than the opponent's closest. An exact closest-distance tie is blank. The scoring team gives up hammer; a blank retains it.\n\nSide walls are legal arcade bank surfaces: rebound into the house or other stones. Passing completely beyond the back line removes a stone. Finish short of fully crossing the far hog line: removed, unless the delivery contacted another in-play stone. The first FIVE deliveries protect opposing free guards outside the house and before the tee: removing one restores ALL previous positions and removes the offending delivery.\n\nAll affected stones must settle. A genuine 70-second simulation failure removes the delivery and restores the prior layout. Rematch preserves setup. This is arcade-scale curling with cab controls, not full tournament fidelity: no human sweepers, no-tick, official clocks, burned-stone adjudication or equipment rules. Pause/disconnect preserves live slides; inputs require release after modal transitions.";
 public override string Header=>Title+"  ·  "+(End>ConfiguredEnds?"EXTRA END "+(End-ConfiguredEnds):"END "+End+" / "+ConfiguredEnds)+"  ·  BLUE "+scores[0]+" : "+scores[1]+" ORANGE";
 public override string Status=>Phase==CurlingPhase.Approach?setup.players[ActiveSlot].name+"  ·  "+(ActiveTeam==0?"BLUE":"ORANGE")+" DELIVERY "+(delivered[ActiveTeam]+1)+" / 8  ·  "+Current.truck.body.linearVelocity.magnitude.ToString("F1")+"m/s  ·  "+Mathf.RoundToInt(Mathf.Clamp01(Current.truck.body.linearVelocity.magnitude/CurlingRules.MaximumEntry)*100)+"% POWER · RELEASE AT THE STRIPE":Phase==CurlingPhase.Slide?"COMMITTED SLIDE  ·  "+(slideTime<4&&usedCurl<curlBudget?"LEFT / RIGHT · EARLY CURL":"PHYSICAL MOMENTUM · WAIT FOR ALL STONES")+"  ·  "+Current.truck.body.linearVelocity.magnitude.ToString("F1")+"m/s":notice;
 public override string Standings{get{text.Clear().Append("HAMMER  ").Append(Hammer==0?"BLUE":"ORANGE").Append("\n\n");for(int i=0;i<setup.count;i++)text.Append(i<teamA?"B ":"O ").Append(setup.players[i].name).Append(i==ActiveSlot?"  <":"").Append('\n');return text.ToString();}}
 public override string Results=>(scores[0]>scores[1]?"BLUE TEAM":"ORANGE TEAM")+" WINS\n\nBLUE  "+scores[0]+" : "+scores[1]+"  ORANGE\n"+EndsScored+" ENDS · "+GuardViolations+" GUARD-ZONE RESTORATIONS\n\n"+Standings;
 protected override void BeginGame(){scores[0]=scores[1]=rosterCursor[0]=rosterCursor[1]=0;Hammer=1;End=1;EndsScored=GuardViolations=PhysicalContacts=0;NewEnd();}
 void NewEnd(){Delivery=delivered[0]=delivered[1]=0;foreach(var s in stones)s.Remove();BeginDelivery();}
 void Layer(Transform root,int layer){root.gameObject.layer=layer;foreach(Transform t in root)Layer(t,layer);}
 void BeginDelivery(){timer=quiet=slideTime=usedCurl=0;notice="";for(int i=0;i<16;i++){var s=stones[i];existed[i]=i<Delivery&&s.InPlay;before[i]=s.truck.body.position;rotations[i]=s.truck.body.rotation;beforeHit[i]=s.HitStone;beforeGuard[i]=s.HitGuard;protectedGuard[i]=existed[i]&&CurlingRules.Protected(Delivery,s.team,ActiveTeam,s.Guard);if(i<Delivery)Layer(s.truck.visuals,2);}Current.Prepare(Delivery,ActiveTeam,ActiveSlot);Layer(Current.truck.visuals,22);cabCamera.view.cullingMask=~(1<<22);cab.SetActive(true);stableYaw=Quaternion.identity;Phase=CurlingPhase.Approach;Plan();Gate();cabCamera.Pose(new Vector3(0,1,-1),new Vector3(0,0,-12),68,true);}
 void Plan(){var level=setup.players[ActiveSlot].difficulty;float noise=level==BowlingDifficulty.Easy?1.5f:level==BowlingDifficulty.Normal?.65f:.18f;aim=new Vector3(UnityEngine.Random.Range(-1f,1f),0,CurlingRules.Tee);bool takeout=false;float closest=999;for(int i=0;i<Delivery;i++)if(stones[i].InPlay&&stones[i].team!=ActiveTeam&&CurlingRules.House(stones[i].truck.body.position)){float d=Vector3.Distance(stones[i].truck.body.position,new Vector3(0,0,CurlingRules.Tee));if(d<closest){closest=d;aim=stones[i].truck.body.position;takeout=true;}}if(!takeout&&Delivery<5&&delivered[ActiveTeam]>0)aim.z=CurlingRules.Hog+4;aim+=new Vector3(UnityEngine.Random.Range(-noise,noise),0,UnityEngine.Random.Range(-noise,noise)*1.3f);bool blocked=false;for(int k=0;k<Delivery;k++)if(stones[k].InPlay){var v=stones[k].truck.body.position;if(v.z>8&&v.z<aim.z-3&&Mathf.Abs(v.x-aim.x*Mathf.Clamp01(v.z/Mathf.Max(1,aim.z)))<CurlingRules.Radius*2)blocked=true;}
 if(blocked&&level!=BowlingDifficulty.Easy&&UnityEngine.Random.value<(level==BowlingDifficulty.Hard?.65f:.3f)){float side=aim.x>0?-1:1;aim.x=side*2*(8.05f-CurlingRules.Radius)-aim.x;}
 float curlError=level==BowlingDifficulty.Easy?.18f:level==BowlingDifficulty.Normal?.07f:.02f;aiCurl=UnityEngine.Random.Range(-curlError,curlError);aimSpeed=Mathf.Sqrt(2*slideDeceleration*Mathf.Max(1,new Vector2(aim.x,aim.z).magnitude))+(Mathf.Abs(aim.x)>8?1.2f:0)+(takeout?2.2f:0)+UnityEngine.Random.Range(-noise*.3f,noise*.3f);}
 Vector2 AI(){var t=Current.truck;if(Phase==CurlingPhase.Slide)return new Vector2(aiCurl,0);var delta=aim-t.body.position;delta.y=0;float wanted=Vector3.SignedAngle(t.transform.forward,delta,Vector3.up);float entryWanted=Mathf.Min(CurlingRules.MaximumEntry,aimSpeed/CurlingRules.ReleaseRatio);float error=entryWanted-Vector3.Dot(t.body.linearVelocity,t.transform.forward);float gas=error<-.25f?Mathf.Clamp(error*.5f,-1,0):Mathf.Clamp(error*.75f,0,1);return new Vector2(Mathf.Clamp(wanted/25,-.4f,.4f),gas);}
 protected override void Simulate(float dt){timer+=dt;if(Phase==CurlingPhase.Approach){var t=Current.truck;var drive=setup.players[ActiveSlot].source==BowlingSource.AI?AI():commands[ActiveSlot];if(t.body.position.z>=0){var velocity=t.body.linearVelocity;var horizontal=new Vector3(velocity.x,0,velocity.z);var released=horizontal.sqrMagnitude>.0001f?horizontal.normalized*CurlingRules.ReleaseSpeed(horizontal.magnitude):Vector3.zero;t.Power(false);t.body.linearVelocity=new Vector3(released.x,velocity.y,released.z);Phase=CurlingPhase.Slide;timer=slideTime=0;stableYaw=Quaternion.Euler(0,t.body.rotation.eulerAngles.y,0);feedback.Play(4,0,true);}else{t.TickDrive(drive);if(timer>35||Mathf.Abs(t.body.position.x)>10.5f||t.body.position.z<CurlingRules.Start-15){Current.Remove();notice="FAILED APPROACH · DELIVERY REMOVED";Resolve(false);}}}
  else if(Phase==CurlingPhase.Slide){slideTime+=dt;var drive=setup.players[ActiveSlot].source==BowlingSource.AI?AI():commands[ActiveSlot];if(Current.InPlay&&slideTime<4&&usedCurl<curlBudget){var v=Current.truck.body.linearVelocity;v.y=0;float cost=Mathf.Abs(drive.x)*earlyCurlRate*dt;float allowed=Mathf.Min(cost,curlBudget-usedCurl);if(cost>0&&v.magnitude>.1f){Current.truck.body.AddForce(Vector3.Cross(Vector3.up,v.normalized)*(Mathf.Sign(drive.x)*v.magnitude*allowed/dt),ForceMode.Acceleration);Current.truck.body.AddTorque(Vector3.up*drive.x*.12f,ForceMode.Acceleration);usedCurl+=allowed;}}
   bool moving=false;for(int i=0;i<=Delivery;i++){var s=stones[i];if(!s.InPlay)continue;var p=s.truck.body.position;if(CurlingRules.SideOrBack(p)||p.y< -1){s.Remove();continue;}var v=s.truck.body.linearVelocity;var flat=new Vector3(v.x,0,v.z);if(flat.magnitude>.045f)s.truck.body.AddForce(-flat.normalized*slideDeceleration,ForceMode.Acceleration);bool small=flat.sqrMagnitude<.004f&&s.truck.body.angularVelocity.sqrMagnitude<.01f;s.quiet=small?s.quiet+dt:0;if(s.quiet>.8f){s.truck.body.linearVelocity=s.truck.body.angularVelocity=Vector3.zero;s.truck.body.Sleep();}moving|=s.Moving;}
   quiet=moving?0:quiet+dt;if(quiet>1)Resolve(false);else if(timer>maximumResolution)Resolve(true);
  }else if(Phase==CurlingPhase.DeliveryResult&&timer>1.7f){if(Delivery>=16)ScoreEnd();else BeginDelivery();}else if(Phase==CurlingPhase.EndResult&&timer>3){if(End>=ConfiguredEnds&&scores[0]!=scores[1]){Phase=CurlingPhase.Complete;EndMatch();}else{End++;NewEnd();}}
 }
 void RestorePrevious(){for(int i=0;i<Delivery;i++){if(existed[i])stones[i].Restore(before[i],rotations[i],beforeHit[i],beforeGuard[i]);else stones[i].Remove();}Physics.SyncTransforms();}
 void Resolve(bool failure){if(Phase!=CurlingPhase.Slide&&Phase!=CurlingPhase.Approach)return;bool violation=false;for(int i=0;i<Delivery;i++)if(protectedGuard[i]&&!stones[i].InPlay)violation=true;if(violation||failure){RestorePrevious();Current.Remove();if(violation){GuardViolations++;notice="FIVE-ROCK GUARD VIOLATION · PRIOR LAYOUT RESTORED";}else notice="SIMULATION RECOVERY · DELIVERY REMOVED, PRIOR LAYOUT RESTORED";}else if(Current.InPlay&&!CurlingRules.HogQualified(Current.truck.body.position,Current.HitStone)){Current.Remove();notice="HOG-LINE VIOLATION · DELIVERY REMOVED";}else if(Current.InPlay)notice=CurlingRules.House(Current.truck.body.position)?"IN THE HOUSE · ALL STONES SETTLED":"GUARD / OPEN ICE · ALL STONES SETTLED";else if(string.IsNullOrEmpty(notice))notice="OUT OF PLAY";Layer(Current.truck.visuals,2);cabCamera.view.cullingMask=~0;cab.SetActive(false);delivered[ActiveTeam]++;rosterCursor[ActiveTeam]++;Debug.Log("CURLING_DELIVERY end="+End+" delivery="+Delivery+" team="+ActiveTeam+" valid="+Current.InPlay+" violation="+violation+" "+notice);Delivery++;Phase=CurlingPhase.DeliveryResult;timer=0;}
 void ScoreEnd(){for(int i=0;i<16;i++){positions[i]=stones[i].truck.body.position;teams[i]=stones[i].team;valid[i]=stones[i].InPlay;}int points=CurlingRules.Score(positions,teams,valid,16,out int team);if(team>=0)scores[team]+=points;Hammer=CurlingRules.HammerAfter(Hammer,team,points);EndsScored++;notice=points==0?"BLANK END · HAMMER RETAINED":(team==0?"BLUE":"ORANGE")+" SCORES "+points+" · HAMMER TO "+(Hammer==0?"BLUE":"ORANGE");Phase=CurlingPhase.EndResult;timer=0;feedback.Play(5,0,true);Debug.Log("CURLING_END end="+End+" points="+points+" team="+team+" total="+scores[0]+":"+scores[1]+" hammer="+Hammer);}
 protected override void Present(float dt){if(cabCamera==null||stones==null)return;foreach(var s in stones)if(s.protectedRing!=null)s.protectedRing.gameObject.SetActive(Running&&s.InPlay&&CurlingRules.Protected(Delivery,s.team,ActiveTeam,s.Guard));if(!Running){cabCamera.Pose(new Vector3(0,1,CurlingRules.SheetCenter),new Vector3(18,135,-135),60);return;}if(Phase==CurlingPhase.Approach||Phase==CurlingPhase.Slide){var body=Current.truck.body;Quaternion yaw=Phase==CurlingPhase.Approach?Quaternion.Euler(0,body.rotation.eulerAngles.y,0):stableYaw;var forward=yaw*Vector3.forward;var seat=body.position+Vector3.up*.82f+forward*.25f;cabCamera.Pose(seat+forward*12,-forward*12,68,true);}else cabCamera.Pose(new Vector3(0,0,CurlingRules.Tee),new Vector3(0,22,-5),60);}
 protected override void StopGame(){if(stones!=null)foreach(var s in stones){s.truck.Power(false);if(!s.truck.body.isKinematic)s.truck.body.linearVelocity=s.truck.body.angularVelocity=Vector3.zero;s.truck.body.isKinematic=true;}}
 protected override void StopSounds(){if(stones!=null)foreach(var s in stones)s.truck.StopSound();}
}
}
